function recordCard(r){return `<button class="record" data-action="record" data-id="${e(r.id)}"><span class="record-top">${pill(r.number)}${pill(r.priority,r.priority==='P1'?'red':'amber')}<span>${e(types[r.type])}</span></span><strong>${e(r.title)}</strong><span class="record-bottom"><span>${e(statuses[r.status])} · ${e(r.assignee||'Sorumlu bekliyor')}</span>${r.due_at?`<b data-sla="${e(r.id)}"></b>`:'<span>İş kaydı</span>'}</span></button>`;}
function eventsPage(){const s=ctx.state,i=s.itsm;return heading('EĞİTİM AKIŞI',`${i.metrics.total} olay. Tek bir işletme.`,'Olay saatleri öneridir. Eğitmen, ekibin yüküne göre kartı gönderir; saat tek başına olay başlatmaz.')+`<div class="flow-tools">${s.scenario.phases.map(p=>`<span class="phase ${s.phase.id===p.id?'current':''}">${e(p.name)} <small>${p.minutes} dk</small></span>`).join('')}</div><div class="timeline">${i.events.slice().sort((a,b)=>a.minute-b.minute).map(ev=>{const r=i.records.find(r=>r.event_id===ev.id),bundle=i.releaseBundles.find(b=>b.events.includes(ev.id));return `<article class="event ${ev.run?'released':''}"><div class="event-time"><b>${ev.id}</b><span>T+${ev.minute}</span></div><div class="event-copy"><div>${pill(ev.process)} ${ev.run?pill(r?.resolved_at?'Sonuç kabul edildi':'Ekipte',r?.resolved_at?'green':'amber'):pill('Hazır')}</div><h2>${e(ev.title)}</h2><p>${e(ev.message)}</p>${bundle?`<p><b>Birlikte gönderilir:</b> ${e(bundle.label)}. Tek işlem, aynı gerçek SLA başlangıcı.</p>`:''}${ctx.user.trainer?`<details><summary>Eğitmen yönlendirmesi</summary><p><b>Beklenen çıktı:</b> ${e(ev.expected)}</p><p><b>Bilgi zarfı:</b> ${e(ev.information)}</p><p><b>İşe dönüş:</b> ${e(ev.debrief)}</p>${ev.prerequisites.length?`<p>Ön koşul: ${ev.prerequisites.join(', ')}</p>`:''}</details>`:''}</div><div class="event-action">${r?button('Kaydı aç →','record',`data-id="${r.id}"`,'secondary'):ctx.user.trainer?button(bundle?'Demeti birlikte gönder':'Ekibe gönder','release',`data-id="${ev.id}"`):''}</div></article>`;}).join('')||'<div class="empty"><h2>İlk kartı bekliyoruz.</h2><p>Olaylar eğitmen gönderdiğinde görünür.</p></div>'}</div>`;}
function servicesPage(){const i=ctx.state.itsm;return heading('ÖNCE HİZMETİ GÖR','Bir parçanın ötesine bakın.','Hayvanlar bireysel CI; bakım yetkinliği, habitat ve ziyaret deneyimi aynı zincirdedir.')+`<label>Hizmet, CI veya ilişki ara<input type="search" data-local-search="services" placeholder="Örn. Mümtaz, pompa, CI-HIPPO"/></label>`+animalCards(ctx.state)+`<div class="service-grid">${i.services.map(s=>`<article class="panel service" data-search-item="services"><div class="eyebrow">${e(s.id)}</div><h2>${e(s.name)}</h2><p>${e(s.promise)}</p>${s.requiresServices?.length?`<p><b>Hizmet ön koşulu:</b> ${s.requiresServices.map(id=>e(i.services.find(x=>x.id===id)?.name||id)).join(' · ')}</p>`:''}<small>HİZMET SAHİBİ</small><b>${e(ctx.state.scenario.roles.find(r=>r.id===s.owner)?.name)}</b><div class="ci-links">${s.cis.map(id=>`<span>${e(i.cis.find(c=>c.id===id)?.name||id)}</span>`).join('')}</div></article>`).join('')}</div><section class="panel table-panel"><h2>CMDB ilişki görünümü</h2><p>İki cihaz aynı kaynağa bağımlı olabilir. Bağlantıyı okuyun, testin kapsamını sorun.</p><div class="table-scroll"><table><thead><tr><th>Varlık</th><th>Kimlik</th><th>Bağımlılık</th><th>Bölge</th></tr></thead><tbody>${i.cis.map(c=>`<tr data-search-item="services"><td>${e(c.name)}${c.state?`<small> · ${e(ciStateLabel(c.state))}</small>`:''}</td><td>${e(c.id)}${i.records.filter(r=>r.ci_id===c.id).map(r=>button(e(r.number),'record',`data-id="${e(r.id)}"`,'quiet')).join('')}</td><td>${e(i.cis.find(x=>x.id===c.dependsOn)?.name||c.dependsOn||'Doğrudan bağımlılık tanımlı değil')}</td><td>${e(ctx.state.scenario.zones.find(z=>z.id===c.zone)?.shortName||c.zone)}</td></tr>`).join('')}</tbody></table></div></section><section class="panel table-panel"><h2>Atölye SLA hedefleri</h2><p>24×7 · Duraklatma yok · Gerçek dakika. Bu tanımlar henüz Niles’ta oluşturulmuş değildir.</p><table><thead><tr><th>Öncelik</th><th>İlk müdahale</th><th>Çözüm</th></tr></thead><tbody>${i.slaPolicies.map(p=>`<tr><td>${p.priority}</td><td>${p.responseMinutes} dk</td><td>${p.resolutionMinutes} dk</td></tr>`).join('')}</tbody></table></section>`;}
function rolesPage(){const s=ctx.state;return heading(`${s.scenario.roles.length} ROL / ORTAK HİZMET`,'Herkesin bir sorumluluğu var.','Rol kartını oku; ihtiyaç duyduğun bilgiyi ilgili ekiple paylaş.')+authorityPanel(s)+`<div class="role-grid">${s.scenario.roles.slice().sort((a,b)=>(b.id===s.roleId)-(a.id===s.roleId)).map(r=>`<article class="panel role-card"><div class="role-top"><span class="role-id">${r.id}</span>${r.id===s.roleId?pill('Senin rolün','green'):''}</div><h2>${e(r.name)}</h2><p>${e(r.goal)}</p><p><b>Sorumluluk</b><br>${e(r.responsibility)}</p>${r.briefing?`<details ${r.id===s.roleId?'open':''}><summary>Özel rol bilgisi ve yetkin</summary><p>${e(r.briefing)}</p><p><b>Yetki:</b> ${e(r.authority)}</p><p><b>İlk adım:</b> ${e(r.steps)}</p><p><b>Çıktı:</b> ${e(r.output)}</p></details>`:''}<details><summary>Kimlerle çalışıyorum?</summary><p>${e(r.partners)}</p></details><div class="role-members">${s.members.filter(m=>m.role_id===r.id).map(m=>e(m.name)).join(' · ')||'Henüz katılımcı atanmamış'}</div></article>`).join('')}</div>`;}
function reportPage(){const i=ctx.state.itsm;return `<section class="panel table-panel"><h2>Eğitmenin kısa kapanış özeti</h2><p>${i.metrics.resolved} sonuç kabul edildi; ${i.metrics.open} kayıt açık. Güncel hizmet: ${i.currentServicesReady?'hazır':'yeniden kontrol gerekiyor'}. Kabul puanı öğrenme ölçümü değildir.</p><p>CSV kayıt özetidir. Bilgi sürümleri, kullanım ve aktarım kanıtı JSON çıktısında ve aşağıdaki öğrenme bölümünde ayrı tutulur.</p></section>`+learningSummary(ctx.state)+heading('KARARLARIN İZİ','Günün sonunda ne değişti?','Çıktıyı, kanıtı ve hizmet deneyimini birlikte değerlendirin.',`<div class="actions">${button('Kayıtları indir','export','','secondary')}${button('Hikâye ve kanıtı indir','evidence','','secondary')}</div>`)+animalPanel(ctx.state,true)+encounterPanel(ctx.state,true)+parkStory()+`<div class="metrics"><article><small>KABUL EDİLEN SONUÇ</small><strong>${i.metrics.resolved}/${i.metrics.total}</strong></article><article><small>ATÖLYE SLA AŞIMI</small><strong data-breach>${i.metrics.breached}</strong></article><article><small>SENARYO KABUL PUANI</small><strong>${i.metrics.score}/${i.metrics.maximum}</strong></article><article><small>NILES KABULÜ</small><strong class="small-value">Doğrulanmadı</strong></article></div><section class="panel table-panel"><h2>Karar ve çalışma günlüğü</h2><label>Aktör, olay veya kanıt ara<input type="search" data-local-search="decisions"/></label>${i.decisions.map(d=>`<article class="decision" data-search-item="decisions"><div>${pill(d.event_id)} <b>${e(d.actor)}</b> <small>${stamp(d.created_at)} · ${e({note:'Çalışma notu',propose:'Ekibin önerisi',evaluate:'Eğitmen kararı'}[d.kind]||d.kind)}</small></div><p>${e(d.note)}</p></article>`).join('')||'<p>Henüz bir çalışma veya karar kaydı yok.</p>'}</section><section class="panel table-panel"><h2>İşe taşıma soruları</h2><ol><li>Hangi anda cihazı değil hizmeti düşündük?</li><li>Hangi kayıt veya ilişki yeniden iş yapmamızı önledi?</li><li>Yarın değiştireceğimiz üç davranışın sahibi, tarihi ve başarı ölçütü ne?</li></ol></section>`;}
function guidePage(){return heading('KISA KURALLAR, GÜÇLÜ DENEYİM','Oyunu nasıl oynuyoruz?',`12–18 teknik katılımcı · 1 eğitmen · ${ctx.state.workshop.duration_seconds/60} dakika`)+`<div class="guide-grid">${ctx.state.scenario.guides.map(g=>`<article class="panel service"><div class="eyebrow">${e(g.category)}</div><h2>${e(g.title.replace('İki saat','Üç ayrı saat'))}</h2><p>${e(g.id==='G5'&&g.content.includes('pompa bağımlılığı düzeltmesi 30 kredi/10 dakika')?"100 oyun kredisi, iki teknisyen; 35 kredi kurtarma rezervidir. Pompa laboratuvarında yeniden başlatma 10 kredi / bir teknisyen / 45 simülasyon saniyesi; bağımsız besleme 45 kredi / iki teknisyen / 120 saniyedir. Tedarik hazırlığı bir teknisyeni 90 saniye meşgul eder, kit maliyetini 35 krediye indirir. Bu işler sunucuda izlenir. Diğer olayların kaynak tercihleri eğitmen kanıtıyla tartışılır; otomatik harcama değildir.":g.content)}</p></article>`).join('')}</div>`;}
function managePage(){if(!ctx.user.trainer)return dashboard();const s=ctx.state;return heading('EĞİTMEN ALANI','Akışı yönet. Öğrenmeye alan aç.','Örnek hesaplar ve yeni atölyeler bu ITSM uygulamasına özeldir.')+`<div class="manage-grid"><section class="panel table-panel"><h2>Oturum saati</h2><p>Gündem durur; SLA gerçek 1× dakika ile devam eder. Baskı saati ayrı kontrol edilir ve yalnız kaynak işlerini etkiler.</p><div class="actions">${button('Başlat','clock','data-op="start"')}${button('Duraklat','clock','data-op="pause"','secondary')}</div><form data-form="phase"><label>Bölüm seç<select name="phase">${s.scenario.phases.map(p=>`<option value="${p.id}" ${s.phase.id===p.id?'selected':''}>${e(p.name)}</option>`).join('')}</select></label><button class="btn secondary">Bölüme geç</button></form></section><section class="panel table-panel"><h2>Prova hesapları</h2><p>Sekiz örnek rol hesabı ve ayrı prova atölyesi oluşturur. Var olan parolaları sıfırlamaz.</p>${button('Örnek hesapları hazırla','demo')}<div id="demo-result"></div></section><section class="panel table-panel"><h2>Yeni atölye</h2><form data-form="workshop"><label>Atölye adı<input name="name" required maxlength="100" placeholder="ITSM · Teknik ekip / 1"/></label><button class="btn primary">Atölyeyi oluştur</button><div class="form-error"></div></form></section><section class="panel table-panel"><h2>Katılımcı ekle</h2><form data-form="member"><label>Ad soyad<input name="name" required maxlength="80"/></label><label>Kullanıcı adı<input name="username" required pattern="[a-z0-9._-]{3,40}"/></label><label>Başlangıç parolası<input type="password" name="password" required minlength="8" autocomplete="new-password"/></label><label>Rol<select name="roleId">${s.scenario.roles.map(r=>`<option value="${r.id}">${e(r.name)}</option>`).join('')}</select></label><button class="btn primary">Katılımcıyı ekle</button><div class="form-error"></div></form></section></div><section class="panel table-panel"><h2>Katılımcılar</h2>${s.members.map(m=>`<div class="member"><span><b>${e(m.name)}</b><small>${e(m.username)}</small></span><select aria-label="${e(m.name)} rolü" data-member="${m.id}">${s.scenario.roles.map(r=>`<option value="${r.id}" ${r.id===m.role_id?'selected':''}>${e(r.name)}</option>`).join('')}</select></div>`).join('')||'<p>Henüz katılımcı yok.</p>'}</section>`;}
function openRecord(id){const i=ctx.state.itsm,r=i.records.find(r=>r.id===id),ev=i.events.find(e=>e.id===r?.event_id);if(!r)return;const key=`itsm-draft-${ctx.user.id}-${ctx.state.workshop.id}-${id}`;
 dialog.innerHTML=`<div class="modal-head"><div>${pill(r.number)} ${pill(types[r.type])} ${pill(r.priority,r.priority==='P1'?'red':'amber')}<h2 id="dialog-title">${e(r.title)}</h2></div>${button('×','close','','quiet')}</div><div class="modal-body"><blockquote>${e(ev.message)}</blockquote><div class="record-facts"><span>Durum<b>${e(statuses[r.status])}</b></span><span>İlk müdahale<b>${stamp(r.ack_at)}</b></span><span>Çözüm hedefi<b>${stamp(r.due_at)}</b></span><span>Çözüm<b>${stamp(r.resolved_at)}</b></span></div>${r.due_at?`<p class="sla-line">Atölye SLA: <strong data-sla="${e(r.id)}"></strong> · Gerçek saat; Niles verisi değildir.</p>`:''}<p><b>Hizmet:</b> ${e(i.services.find(s=>s.id===r.service_id)?.name)}<br><b>CI:</b> ${e(r.ci_id)} ${button('İlişki ve bağlı kayıtları gör','service-context',`data-ci="${e(r.ci_id)}"`,'quiet')}</p><details><summary>Bilgi zarfını aç</summary><p>${e(ev.information)}</p></details>${!r.resolved_at&&!r.ack_at&&r.permissions.ack?button('Üstlen ve ilk müdahaleyi kaydet','ack',`data-id="${id}"`):''}
 ${!r.resolved_at?`<form data-form="record-note" data-record="${e(id)}" data-draft="${e(key)}"><label>Yaptığımız işlem ve kanıtı<textarea name="note" required minlength="5" maxlength="2000" placeholder="Ne yaptınız? Hangi kayıt, saha testi veya kullanıcı teyidi sonucu doğruluyor?">${e(sessionStorage.getItem(key)||'')}</textarea></label><small>Taslak bu sekmede korunur. Çalışma notu en az 5, sonuç önerisi en az 20 karakter somut kanıt ister.</small><div class="actions"><button class="btn secondary" name="intent" value="note">Çalışma notunu kaydet</button>${r.permissions.propose?'<button class="btn primary" name="intent" value="propose">Sonucu eğitmene sun</button>':'<span class="tag">Sonuç önerisi bu kayıt türünün sorumlu rolüne ait</span>'}</div><div class="form-error"></div></form>`:''}
 ${ctx.user.trainer&&!r.resolved_at?`<form class="trainer-evaluation" data-form="evaluate" data-record="${e(id)}"><div class="eyebrow">EĞİTMEN SONUÇ KABULÜ</div><p>${e(ev.expected)}</p><label>Gözlenen sonuç<select name="choiceId" required><option value="">Gözlenen sonucu seçin</option>${ev.choices.map(c=>`<option value="${c.id}">${e(c.label)}</option>`).join('')}</select></label><label>Doğrulanan kanıt<textarea name="note" minlength="20" maxlength="2000" required placeholder="Saha teyidi, kayıt ilişkisi, iletişim veya test sonucunu belirtin."></textarea></label><button class="btn primary">Sonucu kaydet</button><div class="form-error"></div></form>`:''}
 <details><summary>Niles kayıt referansı</summary><p>Elle eklenen bağlantıdır; SLA durumu otomatik doğrulanmaz.</p>${r.niles_url?`<a href="${e(r.niles_url)}" target="_blank" rel="noopener noreferrer">Niles kaydını aç ↗</a>`:''}${r.permissions.niles?`<form data-form="niles" data-record="${e(id)}"><label>Niles staging kayıt adresi<input type="url" name="url" required value="${e(r.niles_url||'')}" placeholder="Niles kayıt adresini yapıştırın"/></label><button class="btn secondary">Referansı kaydet</button><div class="form-error"></div></form>`:'<p>Referansı hizmet masası veya eğitmen ekleyebilir.</p>'}</details><section><h3>Çalışma geçmişi</h3>${i.decisions.filter(d=>d.event_id===ev.id).map(d=>`<article class="decision"><small>${stamp(d.created_at)} · ${e(d.actor)}</small><p>${e(d.note)}</p>${d.actor_id===ctx.user.id&&d.kind==='note'?`${!r.resolved_at&&r.permissions.propose&&d.note.trim().length>=20?button('Bu nottan sonuç sun','propose-note',`data-id="${e(d.id)}" data-record="${e(r.id)}"`,'secondary'):''}${i.learning?.allowed.includes('draft')?`<button class="btn quiet" data-learning="draft" data-event-id="${e(ev.id)}" data-evidence-id="${e(d.id)}">Bu kanıttan bilgi taslağı</button>`:''}${i.learning?.articles.filter(a=>a.status==='published'&&a.authorId!==ctx.user.id&&a.authorRole!==ctx.state.roleId&&a.source.eventId!==ev.id).map(a=>`<button class="btn quiet" data-learning="reuse" data-id="${e(a.id)}" data-event-id="${e(ev.id)}" data-evidence-id="${e(d.id)}">Bu kanıtla sına: ${e(a.title)}</button>`).join('')}`:''}</article>`).join('')||'<p>Henüz çalışma notu yok.</p>'}</section></div>`;
 if(!dialog.open)dialog.showModal();tick();}
async function mutation(data){if(!ctx.state)throw Error('Atölye yükleniyor. Bir an bekleyin.');if(ctx.busy)throw Error('Önceki işlem kaydediliyor. Bir an bekleyin.');ctx.busy=true;const wid=ctx.state.workshop.id,selection=ctx.selection;try{const s=await api(`/api/workshops/${wid}/itsm`,'POST',{...data,requestId:crypto.randomUUID()});if(selection===ctx.selection&&ctx.state?.workshop.id===wid)adopt(s);return s;}finally{ctx.busy=false;}}
function tick(){const s=ctx.state;if(!s)return;const c=$('#connection');if(c){c.textContent=ctx.online?'● Bağlı':'● Bağlantı bekleniyor';c.classList.toggle('offline',!ctx.online);}document.querySelectorAll('[data-clock]').forEach(n=>n.textContent=time(Math.min(s.workshop.duration_seconds,s.workshop.elapsed+(s.workshop.status==='running'&&s.workshop.started_at?Math.max(0,(now()-s.workshop.started_at)/1000):0))));const pressure=s.itsm.encounter;if(pressure){const elapsed=pressure.clock.seconds+(pressure.clock.running?Math.max(0,now()-pressure.clock.at)/1000*pressure.clock.speed:0);document.querySelectorAll('[data-pressure-clock]').forEach(n=>n.textContent=time(elapsed));document.querySelectorAll('[data-job-until]').forEach(n=>n.textContent=time(Math.max(0,Number(n.dataset.jobUntil)-elapsed)));}let breaches=0;
 for(const r of s.itsm.records){if(!r.due_at)continue;const stop=r.resolved_at||now(),left=Math.ceil((r.due_at-stop)/1000),breached=stop>r.due_at;if(breached)breaches++;document.querySelectorAll(`[data-sla="${CSS.escape(r.id)}"]`).forEach(el=>{el.classList.toggle('breached',breached);el.textContent=breached?`SLA aşıldı · ${time(Math.abs(left))}`:r.resolved_at?'SLA içinde':`${time(left)} kaldı`;});}document.querySelectorAll('[data-breach]').forEach(n=>n.textContent=breaches);}
app.addEventListener('input',event=>{const form=event.target.closest('form');if(form)form.dataset.edited='1';if(event.target.closest('#studio-area'))studio.update(event.target);});
