async function onClick(event){const learningButton=event.target.closest('[data-learning]');if(learningButton){dialog.innerHTML=learningForm(ctx.state,learningButton.dataset.learning,learningButton.dataset.id,{eventId:learningButton.dataset.eventId,evidenceId:learningButton.dataset.evidenceId});const form=dialog.querySelector('form');if(form)form.dataset.contextEvidence=learningButton.dataset.evidenceId||'';if(!form){if(!dialog.open)dialog.showModal();return;}form.dataset.learningDraft=`itsm-learning-${ctx.user.id}-${ctx.state.workshop.id}-${learningButton.dataset.learning}-${learningButton.dataset.id||'new'}-${learningButton.dataset.eventId||''}-${learningButton.dataset.evidenceId||''}`;try{const draft=JSON.parse(sessionStorage.getItem(form.dataset.learningDraft)||'{}');for(const [key,value] of Object.entries(draft)){const field=form.elements.namedItem(key);if(field&&field.type!=='hidden')field.value=value;}}catch{}syncLearningUI(dialog);if(!dialog.open)dialog.showModal();return;}const editorButton=event.target.closest('[data-studio]');if(editorButton){if(editorButton.disabled)return;try{if(await studio.action(editorButton)){const area=$('#studio-area');if(area)area.innerHTML=studio.render();}}catch(err){toast(err.message);const out=$('#studio-error');if(out)out.textContent=err.message;}return;}const z=event.target.closest('[data-zone]');if(z){ctx.selected=z.dataset.zone;render();return;}const filter=event.target.closest('[data-filter]');if(filter){ctx.filter=filter.dataset.filter;render();return;}const b=event.target.closest('[data-action]');if(!b||b.disabled)return;const {action,id,view,op}=b.dataset;try{if(action==='close'){dialog.close();return;}if(action==='discard-draft'){const f=dialog.querySelector('form');if(f?.dataset.uxDraft){sessionStorage.removeItem(f.dataset.uxDraft);if(f.dataset.learningDraft)sessionStorage.removeItem(f.dataset.learningDraft);if(f.dataset.draft)sessionStorage.removeItem(f.dataset.draft);f.reset();syncLearningUI(dialog);toast('Bu formun sekmedeki taslağı silindi.');}return;}if(action==='reload-conflict'){await recoverConflict();return;}if(action==='password'){const input=document.querySelector('[name=password]');input.type=input.type==='password'?'text':'password';b.textContent=input.type==='password'?'Parolayı göster':'Parolayı gizle';b.setAttribute('aria-pressed',String(input.type==='text'));return;}if(action==='record'){openRecord(id);return;}if(action==='navigate'){location.hash=view;return;}if(action==='service-context'){dialog.close();ctx.serviceQuery=b.dataset.ci||'';location.hash='services';if(ctx.view==='services')render();return;}if(action==='motion'){ctx.motion=!ctx.motion;localStorage.setItem('itsm-motion',ctx.motion?'on':'off');render();return;}
 b.disabled=true;
 if(action==='logout'){await api('/api/auth/logout','POST',{});ctx.selection++;ctx.user=null;ctx.state=null;sig='';dialog.close();studio.clear();render();}
 if(action==='encounter'){if(op==='plan'){dialog.innerHTML=`<div class="modal-head"><h2 id="dialog-title">Teknik seçenek ve geri dönüş planı</h2>${button('×','close','','quiet')}</div><div class="modal-body"><form data-form="encounter-plan"><label>Müdahale<select name="option"><option value="restart">B1 yeniden başlat · 10 kredi · 1 teknisyen · 45 sn</option><option value="isolate">Bağımsız besleme · ${ctx.state.itsm.encounter.jobs.some(j=>j.type==='support'&&j.done)?35:45} kredi · 2 teknisyen · 120 sn</option></select></label><p>Yeniden başlatma sırasında ağ ve turnike kesilir; 180 sn sonra tekrar riski gerçekleşir. Bağımsız besleme ağ kesintisi yaratmaz; iki teknisyeni meşgul eder, saha kabulü gerekir.</p><label>Test kanıtı ve başarısızlıkta geri dönüş koşulu<textarea name="note" required minlength="20" maxlength="2000" placeholder="Hangi hizmeti, hangi arıza koşulunda test edeceğiz? Başarısız olursa güvenli duruma nasıl döneceğiz?"></textarea></label><button class="btn primary">Planı ekibe sun</button><div class="form-error"></div></form></div>`;if(!dialog.open)dialog.showModal();}else{await mutation({action:'encounter',operation:op,option:b.dataset.option,runtimeRevision:ctx.state.itsm.encounter.revision});toast('Ekip kararı ve kaynak durumu kaydedildi.');}}
 if(action==='animal'){if(['animal_plan','animal_accept','animal_revalidate'].includes(op)){dialog.innerHTML=`<div class="modal-head"><h2 id="dialog-title">${op==='animal_plan'?'Hizmet planı ve güvenli geri dönüş':op==='animal_revalidate'?'Güncel gözlem hizmetini yeniden teyit et':'Yeni ziyaret vaadini teyit et'}</h2>${button('×','close','','quiet')}</div><div class="modal-body"><form data-form="animal"><input type="hidden" name="operation" value="${op}"/>${op==='animal_plan'?'<label>Hizmet planı<select name="option"><option value="partial">Kısmi açılış · 0 kredi · 0 teknisyen · 30 sn</option><option value="delay">Elif vardiyasına ertele · 0 kredi · 1 teknisyen · 180 sn</option><option value="quiet">Sessiz tam gözlem · 20 kredi · 1 teknisyen · 90 sn</option></select></label><p>Tam gözlem ayrıca Elif’in 60 sn erken devrini gerektirir. Kısmi açılışta Mümtaz ziyareti kapalı kalır; 40 kişilik erişilebilir eğitim rotası açılır. Ertelemede Elif normal vardiyasında gelir. Hepsi güvenli başarı olabilir.</p>':''}<label>${op==='animal_plan'?'Kapsam, saha testi ve kapalı alan geri dönüş koşulu':op==='animal_revalidate'?'Güncel su/ağ bağımlılığı ve saha testi kanıtı':'Ziyaretçiye verilen yeni kapsam/süre ve alınan teyit'}<textarea name="note" required minlength="20" maxlength="2000"></textarea></label><button class="btn primary">Kaydet</button><div class="form-error"></div></form></div>`;if(!dialog.open)dialog.showModal();}else{await mutation({action:'animal',operation:op,option:b.dataset.option,runtimeRevision:ctx.state.itsm.encounter.revision});toast('Hayvan hizmeti kararı kaydedildi.');}}
 if(action==='release'){await mutation({action:'release',eventId:id});toast('Olay ekibe gönderildi.');}
 if(action==='propose-note'){const note=ctx.state.itsm.decisions.find(d=>d.id===id&&d.actor_id===ctx.user.id);if(!note)throw Error('Kaynak not bulunamadı.');await mutation({action:'propose',recordId:b.dataset.record,note:note.note});openRecord(b.dataset.record);toast('Seçtiğin kayıtlı not sonuç kanıtı olarak sunuldu.');}
 if(action==='ack'){await mutation({action:'ack',recordId:id});openRecord(id);}
 if(action==='clock'){adopt(await api(`/api/workshops/${ctx.state.workshop.id}/clock`,'POST',{action:op}));toast('Oturum saati güncellendi.');}
 if(action==='demo'){const d=await api('/api/demo-accounts','POST',{});await session(await api('/api/me'));location.hash='manage';render();$('#demo-result').innerHTML=`<p>Başlangıç parolası: <code>${e(d.initialPassword)}</code></p><p>Örnek atölyeyi üst menüden seçin. Değiştirilmiş parolalar korunur.</p><ul>${d.accounts.map(a=>`<li><b>${e(a.username)}</b> · ${e(a.roleName)}</li>`).join('')}</ul>`;}
 if(action==='evidence'){downloadEvidence();}
 if(action==='export'){const i=ctx.state.itsm,lines=[['Kaynak','Kayıt','Tür','Başlık','Öncelik','Durum','İlk müdahale','Hedef','Çözüm','SLA aşıldı','Niles referansı'],...i.records.map(r=>['YEREL SİMÜLASYON — Niles kabulü değildir',r.number,types[r.type],r.title,r.priority,statuses[r.status],r.ack_at?new Date(r.ack_at).toISOString():'',r.due_at?new Date(r.due_at).toISOString():'',r.resolved_at?new Date(r.resolved_at).toISOString():'',r.due_at&&(r.resolved_at||now())>r.due_at?'Evet':'Hayır',r.niles_url||''])];const safe=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const blob=new Blob(['\uFEFF'+lines.map(row=>row.map(safe).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='Mavi-Vadi-ITSM-Oturum-Raporu.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
 }catch(err){toast(err.message);const out=dialog.open?dialog.querySelector('.form-error'):document.querySelector('#action-error');if(out)out.textContent=err.message;}finally{if(b.isConnected)b.disabled=false;}}
document.addEventListener('submit',async event=>{const f=event.target;if(!f.dataset.form)return;event.preventDefault();if(f.dataset.busy)return;f.dataset.busy='1';const err=f.querySelector('.form-error'),input=Object.fromEntries(new FormData(f)),kind=f.dataset.form,btn=event.submitter;if(btn)btn.disabled=true;if(err)err.textContent='';try{
 if(kind==='login'){delete f.dataset.edited;await session(await api('/api/auth/login','POST',input));}
 else if(kind==='learning'){if(input.evidence){[input.eventId,input.evidenceId]=input.evidence.split('|');delete input.evidence;}await mutation({action:'learning',...input,runtimeRevision:Number(input.runtimeRevision)});sessionStorage.removeItem(f.dataset.learningDraft);dialog.close();toast('Bilgi ve öğrenme kanıtı kaydedildi.');clearFormDraft(f);}
 else if(kind==='animal'){await mutation({action:'animal',...input,runtimeRevision:Number(input.runtimeRevision)});clearFormDraft(f);dialog.close();toast('Hizmet kararı kaydedildi.');}
 else if(kind==='encounter-plan'){await mutation({action:'encounter',operation:'plan',...input,runtimeRevision:Number(input.runtimeRevision)});clearFormDraft(f);dialog.close();toast('Plan kaydedildi; kaynak ve değişiklik kararını ilgili roller verecek.');}
 else if(kind==='record-note'){const action=event.submitter?.value||'note';if(action==='propose'&&input.note.trim().length<20)throw Error('Sonucu sunmak için en az 20 karakter somut kanıt yaz. Çalışma notu için 5 karakter yeterlidir.');await mutation({action,recordId:f.dataset.record,note:input.note});sessionStorage.removeItem(f.dataset.draft);openRecord(f.dataset.record);toast('Çalışma kaydedildi.');}
 else if(kind==='evaluate'){await mutation({action:'evaluate',recordId:f.dataset.record,...input});clearFormDraft(f);openRecord(f.dataset.record);toast('Sonuç ve kanıt kaydedildi.');}
 else if(kind==='niles'){await mutation({action:'niles',recordId:f.dataset.record,url:input.url});clearFormDraft(f);openRecord(f.dataset.record);}
 else if(kind==='phase'){delete f.dataset.edited;adopt(await api(`/api/workshops/${ctx.state.workshop.id}/clock`,'POST',{action:'phase',phase:input.phase}));}
 else if(kind==='workshop'){const d=await api('/api/workshops','POST',input);ctx.workshops=(await api('/api/me')).workshops;await selectWorkshop(d.workshop.id);toast('Yeni atölye hazır.');}
 else if(kind==='member'){adopt(await api(`/api/workshops/${ctx.state.workshop.id}/members`,'POST',input));toast('Katılımcı eklendi.');delete f.dataset.edited;render();}
 }catch(error){if(err){err.setAttribute('role','alert');err.textContent=error.message;if(error.status===409){err.insertAdjacentHTML('beforeend','<p>Taslağın korundu. Ekibin güncel durumunu yükle, değişen koşulları kontrol et ve kararı yeniden gönder.</p>'+button('Güncel durumu yükle ve taslağı koru','reload-conflict','','secondary'));}}else toast(error.message);}finally{delete f.dataset.busy;if(btn)btn.disabled=false;}});
for(const eventName of ['input','change'])document.addEventListener(eventName,event=>{if(event.target.matches('[data-learning-filter],select[name=evidence]'))syncLearningUI(document);const form=event.target.closest('[data-learning-draft]');if(form){const draft={};for(const field of form.elements)if(field.name&&field.type!=='hidden')draft[field.name]=field.value;sessionStorage.setItem(form.dataset.learningDraft,JSON.stringify(draft));}});
document.addEventListener('input',event=>{const f=event.target.closest('[data-draft]');if(f&&event.target.name==='note')sessionStorage.setItem(f.dataset.draft,event.target.value);});
app.addEventListener('change',async event=>{const changedForm=event.target.closest('form');if(changedForm)changedForm.dataset.edited='1';try{if(event.target.id==='scenario-import'){await studio.importFile(event.target.files[0]);$('#studio-area').innerHTML=studio.render();return;}if(event.target.id==='workshop'){await selectWorkshop(event.target.value);render();dialog.close();}if(event.target.dataset.member){adopt(await api(`/api/workshops/${ctx.state.workshop.id}/members/${event.target.dataset.member}`,'PATCH',{roleId:event.target.value}));toast('Rol güncellendi.');}}catch(error){toast(error.message);}});
function applySearchFilters(){for(const input of app.querySelectorAll('[data-local-search]')){const group=input.dataset.localSearch,query=input.value.toLocaleLowerCase('tr-TR');app.querySelectorAll(`[data-search-item="${group}"]`).forEach(el=>el.hidden=!el.textContent.toLocaleLowerCase('tr-TR').includes(query));}}
app.addEventListener('input',event=>{if(event.target.dataset.localSearch)applySearchFilters();});
app.addEventListener('keydown',event=>{if(event.target.dataset.zone&&['Enter',' '].includes(event.key)){event.preventDefault();ctx.selected=event.target.dataset.zone;render();}});
window.addEventListener('hashchange',()=>{if(location.hash==='#main'){const main=document.getElementById('main');main?.focus();main?.scrollIntoView();return;}if(['animal-work','pump-work'].includes(location.hash.slice(1))){document.getElementById(location.hash.slice(1))?.scrollIntoView();return;}dialog.close();ctx.view=location.hash.slice(1)||'park';render();window.scrollTo({top:0});});
async function init(){try{ctx.auth=await api('/api/auth/options');if(new URLSearchParams(location.search).get('platform')==='1'){await session(await api('/api/auth/platform','POST',{}));history.replaceState(null,'','/'+location.hash);}else{try{await session(await api('/api/me'));}catch{render();}}}catch(error){render();toast(error.message);}}
window.addEventListener('beforeunload',event=>{if(studio.hasDraft()){event.preventDefault();event.returnValue='';}});
function clearFormDraft(f){if(f.dataset.uxDraft)sessionStorage.removeItem(f.dataset.uxDraft);}
function prepareDrafts(){for(const f of dialog.querySelectorAll('form')){if(f.dataset.uxDraft)continue;const kind=f.dataset.form;if(!['animal','encounter-plan','evaluate','learning','niles'].includes(kind))continue;const operation=f.elements.namedItem('operation')?.value||'',record=f.dataset.record||f.elements.namedItem('articleId')?.value||f.elements.namedItem('transferId')?.value||'';if(['animal','encounter-plan'].includes(kind)){const revision=document.createElement('input');revision.type='hidden';revision.name='runtimeRevision';revision.value=ctx.state.itsm.encounter.revision;f.append(revision);}f.dataset.uxDraft=draftKey(ctx.user.id,ctx.state.workshop.id,kind,operation,record+'-'+(f.dataset.contextEvidence||''));try{restoreFields(f,JSON.parse(sessionStorage.getItem(f.dataset.uxDraft)||'[]'));}catch{}const note=document.createElement('p');note.className='draft-help';note.innerHTML='Taslak bu sekmede, yalnız bu hesap ve atölye için korunur. '+button('Taslağı sil','discard-draft','','quiet');f.append(note);for(const field of f.querySelectorAll('textarea[minlength]:not([aria-describedby])')){const help=document.createElement('small');help.textContent=`En az ${field.minLength}, en fazla ${field.maxLength} karakter.`;field.after(help);}syncLearningUI(dialog);}}
new MutationObserver(prepareDrafts).observe(dialog,{childList:true,subtree:true});
for(const name of ['input','change'])dialog.addEventListener(name,event=>{const f=event.target.closest('[data-ux-draft]');if(f)sessionStorage.setItem(f.dataset.uxDraft,JSON.stringify(captureFields(f)));});
async function recoverConflict(){const f=dialog.querySelector('form');if(!f)return;const wid=ctx.state.workshop.id,selection=ctx.selection;const latest=await api(`/api/workshops/${wid}/state`);if(selection!==ctx.selection||ctx.state?.workshop.id!==wid||!f.isConnected)return;adopt(latest);if(f.elements.namedItem('operation')?.value==='transfer'&&latest.itsm.learning.transfers.some(t=>t.actorId===ctx.user.id)){dialog.innerHTML=learningForm(latest,'transfer');return;}const revision=f.elements.namedItem('runtimeRevision');if(revision)revision.value=latest.itsm.encounter.revision;const err=f.querySelector('.form-error');if(err){const articleId=f.elements.namedItem('articleId')?.value,article=latest.itsm.learning?.articles.find(a=>a.id===articleId);err.innerHTML='<p>Güncel ekip durumu yüklendi. Taslağın değişmedi. Aşağıdaki güncel kanıtı kontrol edip bilinçli olarak tekrar gönder.</p>'+`<section class="conflict-current"><h3>Şu anki ekip durumu</h3><p>Revizyon ${latest.itsm.encounter.revision} · ${latest.itsm.encounter.credits} kredi · ${latest.itsm.encounter.available}/2 teknisyen</p><p>${e(latest.itsm.encounter.next||'')}</p>${article?`<p><b>${e(article.title)}</b> · v${article.version} · ${e(({draft:'Taslak',review:'İnceleme bekliyor',approved:'Yayına uygun',published:'Yayımlanmış',retired:'Emekli'})[article.status]||article.status)}</p><p><b>Koşul:</b> ${e(article.scope)}</p><p><b>Adımlar:</b> ${e(article.procedure)}</p><p><b>Sınırlar/geri dönüş:</b> ${e(article.limits)}</p><p><b>Kaynak kanıt:</b> ${e(article.source?.note||'')}</p><p>${e(article.review?.note||'Bağımsız inceleme henüz yok.')}</p>`:''}<p>Hayvan hizmeti: ${e(({protected:'Güvenli bakım',preparing:'Hazırlanıyor',test_pending:'Saha testi bekliyor',verified:'Saha doğrulandı'})[latest.itsm.animals?.phase]||'Güncel hizmeti kontrol edin')} · plan ${e(({partial:'Kısmi açılış',delay:'Erteleme',quiet:'Sessiz tam gözlem'})[latest.itsm.animals?.plan?.type]||'henüz yok')} · bütçe ${latest.itsm.animals?.funded?'kabul edildi':'bekleniyor'} · risk ${latest.itsm.animals?.approved?'onaylı':'bekleniyor'}</p><h4>Son kayıt kanıtları</h4>${latest.itsm.decisions.slice(0,3).map(d=>`<p>${e(d.actor)} · ${e(d.event_id)}: ${e(d.note)}</p>`).join('')}</section>`;}}
